# 遍历候选里每个引文节点，核验 T[start:end]==quote 且 T.find(quote)==start
import json
T = json.load(open('data/cache/a065244455cfb2221bcda94a.docs.json'))[0]['text']
c = json.load(open('loop/state/out/read_xiyou_L1_0033.candidate.json'))
def walk(o):
    if isinstance(o, dict):
        if 'quote' in o and 'start' in o and 'end' in o:
            yield o
        else:
            for v in o.values():
                yield from walk(v)
    elif isinstance(o, list):
        for v in o:
            yield from walk(v)
ns = list(walk(c))
bad = [n for n in ns if T[n['start']:n['end']] != n['quote'] or T.find(n['quote']) != n['start']]
print('quoteNodes', len(ns), 'mismatch', len(bad))
