# 非空段落覆盖度复算
import json, itertools
T = json.load(open('data/cache/a065244455cfb2221bcda94a.docs.json'))[0]['text']
c = json.load(open('loop/state/out/read_xiyou_L1_0033.candidate.json'))
def walk(o):
    if isinstance(o, dict):
        if 'quote' in o and 'start' in o and 'end' in o:
            yield o
        else:
            for v in o.values():
                yield from walk(v)
    elif isinstance(o, list):
        for v in o:
            yield from walk(v)
cov = set(itertools.chain(*[range(n['start'], n['end']) for n in walk(c)]))
off, paras = 230781, []
for p in T[230781:238725].split('\n\n'):
    if p.strip():
        i = T.find(p, off); paras.append((i, i + len(p))); off = i + len(p)
unc = [1 for a, b in paras if not any(x in cov for x in range(a, b))]
print('paragraphs', len(paras), 'uncovered', len(unc), 'coveredChars', len(cov))
